static case_insensitive_map_t<const TransformFrameOps *> BuildGeneratedTransformFrameOps() {
	case_insensitive_map_t<const TransformFrameOps *> result;
	for (auto &ops : GENERATED_FRAME_OPS) {
		result.emplace(ops.name, &ops);
	}
	return result;
}

const case_insensitive_map_t<const TransformFrameOps *> &PEGTransformerFactory::GeneratedTransformFrameOps() {
	static const case_insensitive_map_t<const TransformFrameOps *> result = BuildGeneratedTransformFrameOps();
	return result;
}

void PEGTransformerFactory::InitializeStatementTrampoline(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &choice_pr = list_pr.Child<ChoiceParseResult>(0);
	auto &choice_result = choice_pr.GetResult();
	process.ReserveChildSlots(1);
	auto child_rule = choice_result.GetRule();
	if (!child_rule) {
		throw InternalException("No transform process registered for rule '%s'", choice_result.Name());
	}
	process.PushChild({*child_rule, choice_result}, 0);
}

arena_ptr<TransformResultValue> PEGTransformerFactory::FinalizeStatementTrampoline(PEGTransformer &transformer,
                                                                                   GeneratedTransformProcess &process) {
	auto result = process.TakeResult<unique_ptr<SQLStatement>>(0);
	if (!transformer.named_parameter_map.empty()) {
		result->named_param_map = transformer.named_parameter_map;
	}
	result->has_anonymous_parameters = transformer.has_anonymous_parameters;
	return transformer.MakeResult<unique_ptr<SQLStatement>>(std::move(result));
}

void PEGTransformerFactory::InitializeIdentifierOrKeywordTrampoline(PEGTransformer &transformer,
                                                                    GeneratedTransformProcess &process) {
	process.ReserveChildSlots(0);
}

