arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeMergeIntoStatementTrampoline(PEGTransformer &transformer,
                                                            GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &dynamic_repeat_pr = list_pr.GetChild(6).Cast<RepeatParseResult>();
	auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
	auto dynamic_child_count = dynamic_repeat_children.size();
	optional<CommonTableExpressionMap> with_clause {};
	if (process.child_results[0]) {
		with_clause = process.TakeResult<CommonTableExpressionMap>(0);
	}
	auto target_opt_alias = process.TakeResult<unique_ptr<BaseTableRef>>(1);
	auto merge_into_using_clause = process.TakeResult<unique_ptr<TableRef>>(2);
	auto join_qualifier = process.TakeResult<JoinQualifier>(3);
	vector<pair<MergeActionCondition, unique_ptr<MergeIntoAction>>> merge_match;
	merge_match.reserve(dynamic_child_count);
	for (idx_t i = 4; i < 4 + dynamic_child_count; i++) {
		merge_match.push_back(process.TakeResult<pair<MergeActionCondition, unique_ptr<MergeIntoAction>>>(i));
	}
	optional<vector<unique_ptr<ParsedExpression>>> returning_clause {};
	if (process.child_results[5 + dynamic_child_count - 1]) {
		returning_clause = process.TakeResult<vector<unique_ptr<ParsedExpression>>>(5 + dynamic_child_count - 1);
	}
	auto result = TransformMergeIntoStatement(transformer, std::move(with_clause), std::move(target_opt_alias),
	                                          std::move(merge_into_using_clause), std::move(join_qualifier),
	                                          std::move(merge_match), std::move(returning_clause));
	return transformer.MakeResult<unique_ptr<SQLStatement>>(std::move(result));
}

